import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { userLogic } from 'scenes/userLogic'

import type { UserType } from '../../types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySeenLogicValues {
    user: UserType | null // userLogic
    isSeen: (key: string) => boolean
    seenLocally: Record<string, boolean>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySeenLogicActions {
    updateHasSeenProductIntroFor: (
        productKey: string,
        value?: boolean | undefined
    ) => {
        productKey: string
        value: boolean
    } // userLogic
    markSeen: (key: string) => {
        key: string
    }
    markUnseen: (key: string) => {
        key: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todaySeenLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isSeen: (seenLocally: Record<string, boolean>, user: UserType | null) => (key: string) => boolean
    }
}

export type todaySeenLogicType = MakeLogicType<
    todaySeenLogicValues,
    todaySeenLogicActions,
    Record<string, any>,
    todaySeenLogicMeta
>

/**
 * Notices and cards in the Today shell that each person sees once. A key is stored on the user's server-side
 * `has_seen_product_intro_for`, so a dismissal holds on every device. Marking a key changes it here at once, and the
 * user record confirms it once it reloads.
 */
export const todaySeenLogic = kea<todaySeenLogicType>([
    path(['layout', 'today', 'todaySeenLogic']),
    connect(() => ({
        values: [userLogic, ['user']],
        actions: [userLogic, ['updateHasSeenProductIntroFor']],
    })),
    actions({
        markSeen: (key: string) => ({ key }),
        markUnseen: (key: string) => ({ key }),
    }),
    reducers({
        seenLocally: [
            {} as Record<string, boolean>,
            {
                markSeen: (state, { key }) => ({ ...state, [key]: true }),
                markUnseen: (state, { key }) => ({ ...state, [key]: false }),
            },
        ],
    }),
    selectors({
        isSeen: [
            (s) => [s.seenLocally, s.user],
            (seenLocally: todaySeenLogicValues['seenLocally'], user: todaySeenLogicValues['user']) =>
                (key: string): boolean =>
                    // Until the user loads, everything counts as seen, so no notice flashes up and goes again.
                    seenLocally[key] ?? (user ? !!user.has_seen_product_intro_for?.[key] : true),
        ],
    }),
    listeners(({ actions }) => ({
        markSeen: ({ key }) => actions.updateHasSeenProductIntroFor(key, true),
        markUnseen: ({ key }) => actions.updateHasSeenProductIntroFor(key, false),
    })),
])
